contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run tries to exercise Collect: we first ensure the Holder has enough recorded balance
    // by calling Put (which may revert). Then call Collect and assert the general invariant.
    // Parameters:
    //  putLock: lockTime to use for Put
    //  putAmount: Ether to send with Put to fund the holder
    //  collectAmount: amount to attempt to collect
    function run(uint putLock, uint putAmount, uint collectAmount) public payable {
        // Ensure this test contract can forward the requested putAmount and collectAmount (collectAmount not sent now)
        require(address(this).balance >= putAmount);

        // Read before-values
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Try to call Put to set up funds for this holder. Capture whether it reverted.
        bool putReverted;
        try c.Put{value: putAmount}(putLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read after Put-values
        (uint midUnlock, uint midHolderBalance) = c.Acc(address(this));
        uint midContractBalance = address(c).balance;

        // Now attempt Collect and capture whether it reverted.
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after Collect-values
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule:
        // - If Collect succeeded (didn't revert) then midHolderBalance >= collectAmount and midHolderBalance - afterHolderBalance == collectAmount
        //   and afterContractBalance <= midContractBalance - collectAmount (contract balance decreased by at least the transferred amount).
        // - If Collect reverted then holder balance and contract balance did not decrease (they are unchanged from mid values).
        assert(
            (!collectReverted && midHolderBalance >= collectAmount && afterHolderBalance + collectAmount == midHolderBalance && midContractBalance >= afterContractBalance + collectAmount)
            || (collectReverted && afterHolderBalance == midHolderBalance && afterContractBalance == midContractBalance)
        );
    }

    // receive to accept Ether sent back by C during Collect
    receive() external payable {}
}

