contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: fund the contract by calling Put with some Ether, ensure MinSum is low so Collect can proceed,
    // then attempt Collect and check the relation between before/after balances and contract storage via public getters.
    function run(uint putLock, uint putAmount, uint minSum, uint collectAmount) public payable {
        // ensure this contract has enough balance to send putAmount
        require(address(this).balance >= putAmount);

        // Initialize MinSum (only allowed before Initialized is called in C). We call SetMinSum via c.
        // Must ensure not to revert: SetMinSum only reverts if intitalized, which is false for fresh c.
        c.SetMinSum(minSum);

        // Record values before Put
        C.Holder memory beforeHolder = c.Acc(address(this));
        uint beforeHolderBalance = beforeHolder.balance;
        uint beforeContractBalance = address(c).balance;

        // Perform Put sending Ether to c
        c.Put{value: putAmount}(putLock);

        // Record values after Put but before Collect
        C.Holder memory midHolder = c.Acc(address(this));
        uint midHolderBalance = midHolder.balance;
        uint midContractBalance = address(c).balance;

        // Check that Put increased both stored balance and contract balance by putAmount
        // If Put didn't revert, these should hold; but we must not assert here — only final assert allowed.

        // Try Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        C.Holder memory afterHolder = c.Acc(address(this));
        uint afterHolderBalance = afterHolder.balance;
        uint afterContractBalance = address(c).balance;

        // Final assert: if Collect succeeded, then holder balance and contract balance both decreased by collectAmount;
        // if Collect reverted, balances remain as after Put (unchanged by the failed Collect call).
        assert(
            (!reverted && midHolderBalance >= collectAmount && afterHolderBalance + collectAmount == midHolderBalance && midContractBalance >= collectAmount && afterContractBalance + collectAmount == midContractBalance)
            || (reverted && afterHolderBalance == midHolderBalance && afterContractBalance == midContractBalance)
        );
    }

    // Allow receiving Ether so this test contract can fund Put
    receive() external payable {}
}

