        // read after-deposit holder balance
        uint afterAcc = c.Acc(address(this)).balance;
        uint afterCbal = address(c).balance;

        // Now attempt Collect of exactly `amount`. Capture whether it reverted.
        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after collect attempt
